 document.querySelectorAll('[data-version]').forEach(b=>b.onclick=()=>{selectedVersion=b.dataset.version;const v=versions.find(x=>x.id===selectedVersion);if(v){parent=v.id;template=v.config.template;updateTemplate(template);$('#factor-name').value=v.name;$('#factor-name').readOnly=true;$('#factor-window').value=v.config.window;$('#factor-direction').value=v.config.direction;$('#factor-hypothesis').value=v.config.hypothesis||'';$('#factor-source-note').textContent='已选历史版本 · 可预览或运行。若要调整参数，请先创建独立名称的新因子。';}refresh().catch(e=>toast(errorCopy(e),true))});
