 $('#factor-save').onclick=()=>safe(async()=>{const name=$('#factor-name').value.trim();if(!name)throw new ApiError(400,{code:'请填写因子名称'});const b={name,template,window:Number($('#factor-window').value),direction:Number($('#factor-direction').value),hypothesis:$('#factor-hypothesis').value.trim()};if(parent&&lib.factor_versions.some(x=>x.id===parent&&x.name===name&&x.config.template===template))b.parent_version_id=parent;const saved=await request('/api/v1/factor-lab/factors',b);selectedVersion=saved.id;toast(`已保存因子 ${saved.name} v${saved.version}`);await refresh()});
